import pytest
from src.data_processor import find_mode

class TestFindMode:
    def test_single_element(self):
        assert find_mode([1]) == 1

    def test_basic_mode(self):
        assert find_mode([1, 1, 2, 3, 3, 3]) == 3

    def test_all_same(self):
        assert find_mode([5, 5, 5, 5]) == 5

    def test_mode_with_tie(self):
        """When multiple elements have same frequency, return the one with max value"""
        assert find_mode([1, 1, 2, 2, 3]) == 2

    def test_mode_complex_tie(self):
        """Complex case with three-way tie, should return max value"""
        assert find_mode([1, 1, 2, 2, 3, 3]) == 3

    def test_empty_list(self):
        assert find_mode([]) is None

    def test_negative_numbers(self):
        assert find_mode([-5, -5, -3, 0]) == -5

